/// <param name = "_contract">NDXRicoKalk2KBVBuildingProjectContract</param>
/// <returns>NDXRicoKalk2KBVBuildingProjectContract</returns>
public NDXRicoKalk2KBVBuildingProjectContract parmContract(NDXRicoKalk2KBVBuildingProjectContract _contract = contract)
{
    contract = _contract;
    return contract;
}

/// <summary>
/// PaffH 03.04.24
