/// <returns>NDXBatchJobRicoBVArgs</returns>
public static NDXBatchJobRicoBVArgs construct()
{
    NDXBatchJobRicoBVArgs args = new NDXBatchJobRicoBVArgs();
    args.parmContract(NDXRicoKalk2KBVBuildingProjectContract::construct());
    return args;
}
